let db;try{db=JSON.parse(localStorage.getItem('fit-demo-v1'))||structuredClone(initial)}catch{db=structuredClone(initial)}
let page='inicio',selected=1,tab='plan',clientFilter='todos',query='',month=9,year=2026,chatClient=1,chartMode='peso',timerSeconds=0,timerRunning=false,timerId;
const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s), client=id=>db.clients.find(c=>c.id===Number(id)), money=n=>'$ '+Number(n).toLocaleString('es-AR');
function persist(){localStorage.setItem('fit-demo-v1',JSON.stringify(db))}
function initials(n){return n.split(' ').map(x=>x[0]).slice(0,2).join('')}
function avatar(c,extra=''){return `<div class="avatar ${extra}" style="background:${esc(c.color)}">${esc(initials(c.name))}</div>`}
function badge(c){return `<span class="badge ${c.active?'':'gray'}">● ${c.active?'Activo':'Inactivo'}</span>`}
function btn(label,action,ic='plus',cls='primary'){return `<button class="${cls}" data-action="${action}">${icon(ic)}${label}</button>`}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('toast-show');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').classList.remove('toast-show'),3300)}
const navGroups=[['GENERAL',[['inicio','Inicio','grid'],['clientes','Mis clientes','users'],['mensajes','Mensajes','chat']]],['ENTRENAMIENTO',[['calendario','Calendario','calendar'],['plantillas','Plantillas','grid'],['ejercicios','Ejercicios','dumbbell'],['nutricion','Nutrición','apple']]],['MI NEGOCIO',[['cobros','Cobros','wallet'],['informes','Informes de ingreso','file'],['herramientas','Herramientas','clock']]]];
function nav(){const active=page==='perfil'?'clientes':page;$('#side-nav').innerHTML=navGroups.map(([label,links])=>`<div class="nav-label">${label}</div>${links.map(([id,name,ic])=>`<button class="nav-link ${active===id?'active':''}" data-go="${id}">${icon(ic)}${name}${id==='mensajes'?'<span class="count">2</span>':''}</button>`).join('')}`).join('');$('#mobile-nav').innerHTML=[['inicio','Inicio','grid'],['clientes','Clientes','users'],['calendario','Calendario','calendar'],['mensajes','Mensajes','chat'],['menu','Menú','menu']].map(([id,n,ic])=>`<button class="${active===id?'active':''}" data-go="${id}">${icon(ic)}${n}</button>`).join('');const labels={inicio:'Inicio',clientes:'Clientes',perfil:'Ficha del cliente',calendario:'Calendario',mensajes:'Mensajes',cobros:'Cobros',informes:'Informes',plantillas:'Plantillas',ejercicios:'Ejercicios',nutricion:'Nutrición',herramientas:'Herramientas',configuracion:'Configuración'};$('#breadcrumb').innerHTML=`Mi espacio <span>/</span> ${labels[page]||'Inicio'}`}
function go(p,id){if(p==='menu'){document.body.classList.toggle('nav-open');return}page=p;if(id)selected=Number(id);if(p==='perfil')tab='plan';document.body.classList.remove('nav-open');render();window.scrollTo(0,0)}
function heading(eyebrow,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${desc}</p></div>${action}</div>`}
function render(){nav();const views={inicio:dashboard,clientes:clientsView,perfil:profileView,calendario:calendarView,mensajes:messagesView,cobros:paymentsView,informes:reportsView,plantillas:templatesView,ejercicios:exercisesView,nutricion:nutritionOverview,herramientas:toolsView,configuracion:settingsView};$('#app').innerHTML=(views[page]||dashboard)();$$('[data-icon]').forEach(el=>{const dot=el.querySelector('i');el.innerHTML=icon(el.dataset.icon)+(dot?'<i></i>':'')});}
function stat(label,value,note,ic){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(ic)}</span></div><div class="metric-value">${value}</div><small>${note}</small><span class="watermark">${icon(ic)}</span></div>`}
function sessionRow(s){const c=client(s.client);if(!c)return '';return `<div class="schedule-row"><div class="time">${s.time}<small>60 min</small></div>${avatar(c)}<div><strong>${esc(c.name)}</strong><small>${esc(s.type)}</small></div><div class="row-end"><span class="badge ${s.done?'':'lime'}">${s.done?'Completada':'Programada'}</span><button class="row-arrow" data-profile="${c.id}" aria-label="Ver ficha de ${esc(c.name)}">${icon('arrow')}</button></div></div>`}
function dashboard(){const active=db.clients.filter(c=>c.active).length,today=db.sessions.filter(s=>s.date==='2026-10-24');return `<div class="page-heading"><div><div class="eyebrow">TU CENTRO DE ENTRENAMIENTO</div><h1>Todo listo para seguir creciendo.</h1></div>${btn('Nuevo cliente','new-client')}</div><section class="hero"><div><div class="date-chip"><span class="online-dot"></span> Sábado, 24 de octubre de 2026</div><h1>Buenas tardes, <span>Fede</span> 👋</h1><p>Un nuevo día para acompañar a tus clientes.<br>Este es el resumen de tu espacio.</p></div><div class="hero-art">${icon('dumbbell')}</div></section><div class="stats">${stat('Clientes totales',db.clients.length,`<span>↗ ${active} activos</span> en tu equipo`,'users')}${stat('Planes activos',active,'Entrenamientos en curso','dumbbell')}${stat('Sesiones hoy',today.length,'Tu agenda del día','calendar')}${stat('Entrenaron hoy',today.filter(s=>s.done).length,'<span>✓ Buen trabajo</span> sesiones completadas','circleCheck')}</div><div class="dashboard-grid"><div><section class="card"><div class="card-header"><div><h2>Tu agenda de hoy</h2><small>Acompañá cada paso de su progreso.</small></div><button class="text-button" data-go="calendario">Ver calendario ↗</button></div>${today.map(sessionRow).join('')||'<p>No hay sesiones programadas.</p>'}</section><div class="quick-actions">${btn('Agendar sesión','new-session','calendar','ghost')}${btn('Crear rutina','new-plan','dumbbell','ghost')}${btn('Registrar cobro','new-payment','wallet','ghost')}</div><section class="card" style="margin-top:22px"><div class="card-header"><h2>Clientes en movimiento</h2><button class="text-button" data-go="clientes">Ver todos ↗</button></div>${db.clients.filter(c=>c.active).slice(0,3).map(c=>`<div class="client-row">${avatar(c)}<div><strong>${esc(c.name)}</strong><small>${esc(c.goal)}</small></div><div class="row-end">${badge(c)}<button class="row-arrow" data-profile="${c.id}" aria-label="Abrir ficha">${icon('arrow')}</button></div></div>`).join('')}</section></div><div><section class="card"><div class="card-header"><div><h2>Constancia que se nota</h2><small>Sesiones completadas esta semana</small></div><span class="badge lime">↗ 18%</span></div><div style="display:flex;align-items:baseline;gap:8px;margin:20px 0"><span class="metric-value" style="margin:0">24</span><span class="muted" style="font-size:10px">de 30 sesiones programadas</span></div><svg class="mini-chart" viewBox="0 0 320 95" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b5ed39" stop-opacity=".25"/><stop offset="1" stop-color="#b5ed39" stop-opacity="0"/></linearGradient></defs><path d="M0 75Q24 80 50 55T100 60 155 38 210 42 265 15 320 5V95H0Z" fill="url(#area)"/><path d="M0 75Q24 80 50 55T100 60 155 38 210 42 265 15 320 5" stroke="#b5ed39" fill="none" stroke-width="2.5"/></svg><div class="chart-labels"><span>LUN</span><span>MAR</span><span>MIÉ</span><span>JUE</span><span>VIE</span><span>SÁB</span><span>DOM</span></div></section><section class="card" style="margin-top:22px"><div class="card-header"><h2>Última actividad</h2><span class="online-dot"></span></div>${[['circleCheck','Natalia completó su entrenamiento','Piernas · Día 1 · Energía 5/5','Hace 25 minutos'],['chart','Martín registró un nuevo peso','Progreso actualizado · 82 kg','Hace 1 hora'],['wallet','Pago recibido de Virginia','Plan mensual · $ 35.000','Hace 2 horas']].map(a=>`<div class="activity"><div class="activity-icon">${icon(a[0])}</div><div><strong>${a[1]}</strong><p>${a[2]}</p><time>${a[3]}</time></div></div>`).join('')}</section></div></div>`}
function clientsView(){return heading('TU EQUIPO','Mis clientes',`${db.clients.length} personas, muchos objetivos. Un mismo compromiso.`,btn('Nuevo cliente','new-client'))+`<div class="toolbar"><div class="search-field">${icon('search')}<input id="client-search" placeholder="Buscar por nombre o email..." value="${esc(query)}" aria-label="Buscar cliente"></div><select id="status-filter" aria-label="Filtrar clientes"><option value="todos" ${clientFilter==='todos'?'selected':''}>Todos los estados</option><option value="activos" ${clientFilter==='activos'?'selected':''}>Activos</option><option value="inactivos" ${clientFilter==='inactivos'?'selected':''}>Inactivos</option></select></div><div class="client-grid" id="client-results">${clientCards()}</div>`}
function clientCards(){const list=db.clients.filter(c=>(clientFilter==='todos'||c.active===(clientFilter==='activos'))&&`${c.name} ${c.email}`.toLowerCase().includes(query.toLowerCase()));return list.map(c=>{const next=db.sessions.find(s=>s.client===c.id&&!s.done);return `<article class="client-card" data-profile="${c.id}" tabindex="0" role="button" aria-label="Ver ficha de ${esc(c.name)}"><div class="client-card-top">${avatar(c)}<div><h3>${esc(c.name)}</h3><small>${esc(c.email)}</small></div><span class="row-arrow">${icon('arrow')}</span></div><div class="badges">${badge(c)}<span class="badge gray">${esc(c.goal)}</span></div><div class="client-card-bottom"><span class="inline">${icon('calendar')}${next?`${next.date.slice(8)} oct · ${next.time}`:'Sin sesiones programadas'}</span><span>Ver ficha →</span></div></article>`}).join('')||'<div class="empty-result">No encontramos clientes con esa búsqueda.</div>'}
const profileTabs=[['plan','Plan','file'],['nutricion','Nutrición','apple'],['progreso','Progreso','chart'],['calendario','Calendario','calendar'],['cobros','Cobros','wallet'],['informes','Informes','file'],['datos','Perfil','person']];
function profileView(){const c=client(selected);if(!c){page='clientes';return clientsView()}return `<button class="back" data-go="clientes">${icon('left')}Volver a mis clientes</button><div class="profile-top"><div class="profile-person">${avatar(c)}<div><h1>${esc(c.name)}</h1><div class="profile-meta">${badge(c)}<span>· ${esc(c.goal)}</span></div></div></div><div class="profile-actions">${btn('<span>Mensaje</span>','client-chat','chat','ghost')}${btn('<span>Editar</span>','edit-client','edit','ghost')}${btn(`<span>${c.active?'Archivar':'Activar'}</span>`,'archive-client','person','ghost')}</div></div><div class="tabs" role="tablist">${profileTabs.map(([id,n,ic])=>`<button class="tab ${tab===id?'active':''}" role="tab" aria-selected="${tab===id}" data-tab="${id}">${icon(ic)}${n}</button>`).join('')}</div><div id="tab-content">${({plan:planView,nutricion:nutritionView,progreso:progressView,calendario:()=>calendarContent(c.id),cobros:()=>paymentsContent(c.id),informes:()=>reportCard(c),datos:()=>clientData(c)})[tab]()}</div>`}
const defaults=[{name:'Piernas & glúteos',items:[['PIERNAS','Sentadilla con barra','4 × 12 / 10 / 10 / 8','90 s de descanso. Aumentá la carga progresivamente.'],['GLÚTEOS','Hip thrust con barra','4 × 12','60 s de descanso. Pausa de un segundo arriba.'],['PIERNAS','Prensa inclinada','3 × 15','60 s de descanso. Mantené un rango controlado.'],['ISQUIOTIBIALES','Curl femoral sentado','3 × 12','60 s de descanso. Controlá la fase de vuelta.']]},{name:'Tren superior',items:[['ESPALDA','Jalón al pecho','4 × 12','90 s de descanso. Evitá balancear el torso.'],['PECHO','Press con mancuernas','4 × 10','90 s de descanso. Movimiento lento y controlado.'],['HOMBROS','Elevaciones laterales','3 × 15','60 s de descanso. Sin impulso.'],['BÍCEPS','Bíceps con cuerda en polea','3 × 12','60 s de descanso. Codos estables.']]}];
function planView(){const c=client(selected),p=db.plans[selected]||{name:c.plan,weeks:3};return `<div class="plan-heading"><div><div class="eyebrow">ENTRENAMIENTO PERSONALIZADO</div><h2>${esc(p.name)}</h2><p>${esc(p.weeks)} semanas de entrenamiento · Nivel intermedio</p></div><div class="button-group">${btn('Guardar plantilla','save-template','bookmark','ghost')}${btn('Editar plan','edit-plan','edit','ghost')}</div></div><div class="days-grid">${defaults.map((d,i)=>`<section class="day-card"><div class="day-header"><div class="eyebrow" style="margin-bottom:4px">PLAN DE ENTRENAMIENTO</div><div class="day-header-top"><div><div class="day-title">DÍA ${i+1}</div><p>${esc(p['day'+i]||d.name)}</p></div><span class="badge lime">${d.items.length} EJERCICIOS</span></div><div class="motto">FUERZA · DISCIPLINA · CONSTANCIA</div></div>${d.items.map((e,j)=>`<div class="exercise"><span class="muscle ${i?'purple':''}">${e[0]}</span><div class="exercise-main"><span class="exercise-name">${icon('dumbbell')}${e[1]}</span><span class="sets">${esc(p['set'+i+j]||e[2])}</span><button class="exercise-toggle" data-action="exercise-note" aria-label="Ver indicaciones">${icon('info')}</button></div><p class="inline">${icon('repeat')} ${e[3]}</p><div class="exercise-note notice">Completá cada repetición con técnica controlada. Registrá la carga utilizada al finalizar la sesión.</div></div>`).join('')}</section>`).join('')}</div><div class="notice inline">${icon('info')} Rutina ilustrativa para mostrar el funcionamiento de la plataforma.</div>`}
function nutritionView(){const n=db.nutrition[selected];if(!n)return `<section class="empty">${icon('apple')}<h2>Un plan que acompañe su objetivo.</h2><p>Todavía no hay un plan nutricional asignado.<br>Organizá las comidas y recomendaciones de tu cliente.</p>${btn('Crear plan nutricional','new-nutrition')}</section>`;return `<div class="plan-heading"><div><div class="eyebrow">ALIMENTACIÓN</div><h2>${esc(n.name)}</h2><p>Guía de organización diaria · ${esc(n.calories)} kcal de referencia</p></div>${btn('Editar plan','new-nutrition','edit','ghost')}</div><section class="card">${[['08:00','Desayuno',n.breakfast],['13:00','Almuerzo',n.lunch],['17:00','Merienda',n.snack],['21:00','Cena',n.dinner]].map(m=>`<div class="meal"><span class="meal-time">${m[0]}</span><h3>${m[1]}</h3><p>${esc(m[2])}</p></div>`).join('')}<div class="notice">Contenido de ejemplo. Los planes reales deben ser definidos por el profesional correspondiente.</div></section>`}
function progressView(){const checkin=(db.checkins||{})[selected];return `<div class="progress-summary"><div class="card"><span>Peso actual</span><strong>${client(selected).weight} <span>kg</span></strong><small>−2,5 kg desde el inicio</small></div><div class="card"><span>Adherencia</span><strong>86<span>%</span></strong><div class="bar"><i style="width:86%"></i></div></div><div class="card"><span>Sesiones completadas</span><strong>12 <span>/ 14</span></strong><small>En las últimas 4 semanas</small></div></div><div class="two-cols"><section class="card"><div class="card-header"><div><h2>Evolución en el tiempo</h2><small>Registro de las últimas semanas</small></div><select id="chart-mode" aria-label="Métrica de progreso"><option value="peso" ${chartMode==='peso'?'selected':''}>Peso corporal</option><option value="carga" ${chartMode==='carga'?'selected':''}>Carga en sentadilla</option></select></div>${progressChart()}<div class="chart-labels"><span>3 OCT</span><span>10 OCT</span><span>17 OCT</span><span>24 OCT</span></div></section><section class="card"><div class="card-header"><h2>Check-in semanal</h2>${icon('activity')}</div><div class="list-data"><span class="muted">Último registro</span><b>24 de octubre</b></div><div class="list-data"><span class="muted">Energía</span><b style="color:var(--lime)">${esc(checkin?.energy||5)} / 5</b></div><div class="list-data"><span class="muted">Sueño</span><b>7 a 8 horas</b></div><div class="list-data"><span class="muted">Sensación</span><b>Muy bien</b></div><div style="margin-top:22px">${btn('Registrar check-in','checkin','plus','ghost')}</div></section></div><section class="card" style="margin-top:20px"><div class="card-header"><h2>Evolución de cargas y marcas</h2><span class="badge lime">MEJOR MARCA</span></div><div class="list-data"><span>Bíceps con cuerda en polea</span><b style="color:var(--lime)">20 kg <small>+2,5 kg este mes</small></b></div><div class="list-data"><span>Sentadilla con barra</span><b style="color:var(--lime)">50 kg <small>+10 kg este mes</small></b></div>${db.notes[selected]?`<div class="notice">Última nota: ${esc(db.notes[selected])}</div>`:''}</section>`}
function progressChart(){const up=chartMode==='carga',w=client(selected).weight;const vals=up?[40,42.5,47.5,50]:[w+2.5,w+1.5,w+.7,w];const ys=up?[180,150,85,50]:[45,100,150,185];return `<svg class="progress-chart" viewBox="0 0 500 220" role="img" aria-label="${up?'Aumento de carga':'Evolución del peso'} en cuatro semanas"><defs><linearGradient id="progressarea" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b5ed39" stop-opacity=".15"/><stop offset="1" stop-color="#b5ed39" stop-opacity="0"/></linearGradient></defs>${[40,90,140,190].map(y=>`<path d="M20 ${y}H480" stroke="var(--line)" stroke-dasharray="4 5"/>`).join('')}<path d="M30 ${ys[0]}L175 ${ys[1]}L320 ${ys[2]}L465 ${ys[3]}V210H30Z" fill="url(#progressarea)"/><path d="M30 ${ys[0]}L175 ${ys[1]}L320 ${ys[2]}L465 ${ys[3]}" fill="none" stroke="#b5ed39" stroke-width="3"/>${ys.map((y,i)=>`<circle cx="${30+i*145}" cy="${y}" r="5" fill="#b5ed39"/><text x="${30+i*145}" y="${y-16}" text-anchor="middle">${vals[i]} kg</text>`).join('')}</svg>`}
function calendarView(){return heading('ORGANIZÁ TU DÍA','Calendario','Cada sesión es un paso más hacia su objetivo.',btn('Agendar sesión','new-session','calendar'))+calendarContent()}
function calendarContent(id){const label=new Date(year,month).toLocaleDateString('es-AR',{month:'long',year:'numeric'});let first=(new Date(year,month,1).getDay()+6)%7,days=new Date(year,month+1,0).getDate();const sessions=db.sessions.filter(s=>!id||s.client===id);return `<div class="two-cols" style="grid-template-columns:1fr"><section class="card calendar-card"><div class="calendar-head"><h2 style="text-transform:capitalize">${label}</h2><div class="button-group"><button class="icon-btn" data-action="month-prev" aria-label="Mes anterior">${icon('left')}</button><button class="small ghost" data-action="month-today">Hoy</button><button class="icon-btn" data-action="month-next" aria-label="Mes siguiente">${icon('right')}</button>${id?btn('Agendar','new-session','plus','primary small'):''}</div></div><div class="calendar-grid">${['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:first},()=>'<div class="calendar-day blank"></div>').join('')}${Array.from({length:days},(_,i)=>{const date=`${year}-${String(month+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,events=sessions.filter(s=>s.date===date);return `<button class="calendar-day ${date==='2026-10-24'?'today':''}" data-date="${date}" aria-label="${i+1} ${label}: ${events.length} sesiones"><span>${i+1}</span>${events.slice(0,2).map((s,j)=>`<div class="calendar-event ${j?'blue':''}">${s.time} · ${esc(client(s.client)?.name.split(' ')[0]||'Cliente')}</div>`).join('')}${events.length>2?`<small>+${events.length-2}</small>`:''}</button>`}).join('')}</div><div class="calendar-legend"><span>● Sesión de entrenamiento</span><span style="color:var(--lime)">● Hoy</span></div></section></div><section class="card" style="margin-top:20px"><div class="card-header"><h2>Próximas sesiones</h2><span class="badge lime">${sessions.filter(s=>!s.done).length} programadas</span></div>${sessions.filter(s=>!s.done).map(s=>`<div style="font-size:10px;color:var(--muted);margin-top:15px">${s.date.split('-').reverse().join('/')}</div>${sessionRow(s)}`).join('')||'<p>No hay sesiones pendientes.</p>'}</section>`}
function paymentsView(){return heading('TU NEGOCIO','Cobros','El estado de tus planes y pagos, siempre claro.',btn('Registrar cobro','new-payment','wallet'))+paymentsContent()}
function paymentsContent(id){const list=db.payments.filter(p=>!id||p.client===id),paid=list.filter(p=>p.paid).reduce((s,p)=>s+p.amount,0),pending=list.filter(p=>!p.paid).reduce((s,p)=>s+p.amount,0);return `<div class="stats money-stats" style="grid-template-columns:repeat(3,1fr)">${stat('Cobrado',money(paid),'Pagos registrados','wallet')}${stat('Pendiente',money(pending),pending?'Por cobrar':'Cuenta al día','clock')}${stat('Movimientos',list.length,'En este período','file')}</div>${id?`<div class="button-group" style="margin-bottom:20px">${btn('Registrar pago','new-payment','plus')}${btn('Nuevo cargo','new-charge','wallet','ghost')}</div>`:''}<section class="card"><div class="card-header"><h2>Movimientos de octubre</h2><button class="text-button" data-action="export-payments">Exportar CSV ↗</button></div><div class="table-wrap"><table><thead><tr><th>CLIENTE</th><th>CONCEPTO</th><th>FECHA</th><th>IMPORTE</th><th>ESTADO</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td>${esc(client(p.client)?.name||'Cliente')}</td><td>Plan mensual</td><td>${p.date.split('-').reverse().join('/')}</td><td>${money(p.amount)}</td><td><span class="badge ${p.paid?'':'yellow'}">${p.paid?'Pagado':'Pendiente'}</span></td><td>${p.paid?`<span class="muted">${esc(p.method)}</span>`:`<button class="small ghost" data-paid="${p.id}">Marcar pagado</button>`}</td></tr>`).join('')}</tbody></table>${!list.length?'<p style="padding:30px">Sin movimientos registrados.</p>':''}</div></section>`}
function reportCard(c){return `<section class="card"><div class="activity" style="border:0;padding:0"><div class="activity-icon" style="width:44px;height:44px">${icon('file')}</div><div><h2>Informe de ingreso</h2><p style="font-size:12px;margin-top:7px">Objetivo, experiencia, disponibilidad y hábitos declarados por ${esc(c.name.split(' ')[0])}.</p><small>Completado el 17 de octubre de 2026</small><div style="margin-top:20px">${btn('Ver informe / PDF',`report-${c.id}`,'file')}</div></div></div><div class="notice">¿Es momento de volver a evaluar? Podés actualizar los datos desde la pestaña Perfil.</div></section>`}
function reportHTML(c){return `<article class="report-paper"><div class="eyebrow" style="color:#75a710">FIT TRAINING STUDIO · DEMO</div><h1>Informe de ingreso · ${esc(c.name)}</h1><p>Completado el 17 de octubre de 2026 · ${esc(c.email)}</p><div class="report-grid">${[['EDAD',c.age+' años'],['NIVEL','Intermedio'],['ALTURA',c.height+' cm'],['PESO',c.weight+' kg'],['DÍAS / SEMANA','4 días'],['DURACIÓN DE SESIÓN','60 minutos']].map(([k,v])=>`<div class="report-field"><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div><h3>Objetivo</h3><div class="report-section">${esc(c.goal)}. Mejorar la constancia y el bienestar general.</div><h3>Experiencia y disponibilidad</h3><div class="report-section">Entrenamiento en gimnasio · Horario preferido: tarde.<br>Experiencia previa: entrenamiento de fuerza, nivel intermedio.</div><h3>Salud</h3><div class="report-section">Lesiones declaradas: ninguna.<br>Condiciones médicas declaradas: ninguna.<br>Medicación declarada: ninguna.</div><h3>Hábitos y estilo de vida</h3><div class="report-section">Sueño: 7 a 8 horas · Alimentación: organizada.<br>Actividad diaria: moderada.</div><p style="margin-top:25px">Informe ilustrativo con datos ficticios para la demostración.</p></article>`}
function reportsView(){return heading('CONOCÉ A TU EQUIPO','Informes de ingreso','La información inicial de cada cliente, en un solo lugar.')+`<section class="card">${db.clients.map(c=>`<div class="client-row">${avatar(c)}<div><strong>${esc(c.name)}</strong><small>${esc(c.goal)}</small></div><div class="row-end">${btn('Ver informe',`report-${c.id}`,'file','ghost small')}</div></div>`).join('')}</section>`}
function clientData(c){return `<div class="two-cols"><section class="card"><div class="card-header"><h2>Datos personales</h2>${btn('Editar','edit-client','edit','ghost small')}</div>${[['Nombre completo',c.name],['Email',c.email],['Edad',c.age+' años'],['Altura',c.height+' cm'],['Peso',c.weight+' kg'],['Objetivo',c.goal]].map(([k,v])=>`<div class="list-data"><span class="muted">${k}</span><strong>${esc(v)}</strong></div>`).join('')}</section><section class="card"><h2>Gestión del cliente</h2><p style="font-size:12px;margin:15px 0 25px">Actualizá su estado o administrá la ficha de este cliente de demostración.</p><div class="button-group">${btn(c.active?'Archivar cliente':'Activar cliente','archive-client','person','ghost')}${btn('Eliminar','delete-client','trash','ghost danger')}</div></section></div>`}
function messagesView(){const c=client(chatClient)||db.clients[0];if(!c)return heading('COMUNICACIÓN','Mensajes','Agregá un cliente para comenzar.');chatClient=c.id;return heading('SIEMPRE CERCA','Mensajes','Un espacio para acompañar, consultar y motivar.')+`<section class="card messages-layout"><div class="conversation-list">${db.clients.filter(x=>x.active).map(x=>`<div class="conversation ${x.id===c.id?'active':''}" data-chat="${x.id}" tabindex="0" role="button">${avatar(x)}<div><strong>${esc(x.name)}</strong><p>${x.id===1?'¡Gracias, Fede! 💪':'Ver conversación'}</p></div></div>`).join('')}</div><div class="chat"><div class="chat-top"><b>${esc(c.name)}</b><small><span style="color:var(--green)">●</span> Conversación de demostración</small></div><div class="chat-messages" id="chat-messages"><div class="bubble">¡Hola, Fede! Ya completé la rutina de hoy. Me sentí con mucha energía.<small>09:45</small></div><div class="bubble sent">¡Excelente! Seguí así. En la próxima sesión revisamos cómo venís con las cargas 💪<small>10:02 · ✓✓</small></div>${db.messages.filter(m=>m.client===c.id).map(m=>`<div class="bubble sent">${esc(m.text)}<small>Ahora · Guardado en demo</small></div>`).join('')}</div><form class="chat-form" id="chat-form"><input name="message" placeholder="Escribí un mensaje..." aria-label="Mensaje" required autocomplete="off"><button type="submit" class="primary" aria-label="Enviar mensaje en demo">${icon('send')}</button></form></div></section><div class="notice">Los mensajes se guardan únicamente en esta demo. No se envían a personas reales.</div>`}
const templateNames=['Hipertrofia 1','Fuerza inicial','Rendimiento total'];
function templatesView(){return heading('TU BIBLIOTECA','Plantillas de entrenamiento','Creá una base, personalizá cada experiencia.',btn('Crear plantilla','new-plan'))+`<div class="resource-grid">${[...templateNames,...(db.templates||[])].map((n,i)=>`<section class="card resource-card"><div class="resource-visual">${icon('dumbbell')}</div><span class="badge lime">${i===0?'INTERMEDIO':'TODOS LOS NIVELES'}</span><h2 style="margin-top:13px">${esc(n)}</h2><p>${i===0?'3 semanas · 2 días de entrenamiento':'4 semanas · Entrenamiento personalizado'}<br>Ejercicios, series y descansos organizados.</p><button class="ghost" data-template="${esc(n)}">${icon('plus')}Asignar a un cliente</button></section>`).join('')}</div>`}
function exercisesView(){const all=defaults.flatMap(d=>d.items);return heading('TÉCNICA & MOVIMIENTO','Biblioteca de ejercicios','Una base de movimientos para armar cada rutina.')+`<div class="toolbar"><div class="search-field">${icon('search')}<input id="exercise-search" placeholder="Buscar ejercicio o grupo muscular..." aria-label="Buscar ejercicio"></div></div><div class="resource-grid" id="exercise-results">${exerciseCards(all)}</div>`}
function exerciseCards(list){return list.map(e=>`<section class="card resource-card"><div class="resource-visual">${icon('dumbbell')}</div><span class="muscle">${e[0]}</span><h2>${e[1]}</h2><p>${e[3]}</p><button class="ghost" data-technique="${esc(e[1])}">${icon('info')}Ver indicaciones</button></section>`).join('')||'<div class="empty-result">No encontramos ejercicios.</div>'}
function nutritionOverview(){return heading('ACOMPAÑAMIENTO INTEGRAL','Nutrición','Organizá los planes de alimentación de tu equipo.')+`<section class="card">${db.clients.filter(c=>c.active).map(c=>`<div class="client-row">${avatar(c)}<div><strong>${esc(c.name)}</strong><small>${db.nutrition[c.id]?esc(db.nutrition[c.id].name):'Sin plan asignado'}</small></div><div class="row-end"><button class="small ghost" data-nutrition="${c.id}">${icon('apple')}Ver plan</button></div></div>`).join('')}</section>`}
function toolsView(){return heading('TU CAJA DE HERRAMIENTAS','Cada detalle cuenta.','Pequeñas herramientas para acompañar el entrenamiento.')+`<div class="resource-grid"><section class="card"><div class="eyebrow">CONTROLÁ LOS TIEMPOS</div><h2>Cronómetro</h2><div id="timer" class="timer">${formatTime(timerSeconds)}</div><div class="button-group" style="justify-content:center">${btn(timerRunning?'Pausar':'Iniciar','timer-toggle',timerRunning?'pause':'play')}${btn('Reiniciar','timer-reset','repeat','ghost')}</div></section><section class="card"><div class="eyebrow">ACTIVIDAD DIARIA</div><h2>Registro de pasos</h2><div class="metric-value" style="margin:30px 0 10px">${Number(db.steps||7250).toLocaleString('es-AR')}<span class="muted" style="font-size:17px"> / 10.000</span></div><p style="font-size:11px">Una meta diaria, un hábito a la vez.</p><div class="bar" style="margin-bottom:30px"><i style="width:${Math.min((db.steps||7250)/100,100)}%"></i></div>${btn('Actualizar pasos','steps','steps','ghost')}<small>Registro manual de demostración</small></section><section class="card"><div class="eyebrow">REGISTRO NUTRICIONAL</div><h2>Medición calórica</h2><div class="metric-value" style="margin:30px 0 10px">${Number(db.calories||1850).toLocaleString('es-AR')}<span class="muted" style="font-size:17px"> kcal</span></div><p style="font-size:11px">Registro manual del consumo diario.</p><div class="bar" style="margin-bottom:30px"><i style="width:${Math.min((db.calories||1850)/22,100)}%"></i></div>${btn('Registrar consumo','calories','fire','ghost')}<small>No calcula necesidades individuales.</small></section></div>`}
function formatTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function settingsView(){return heading('TU ESPACIO','Configuración','Personalizá tu experiencia en esta demo.')+`<section class="card"><div class="setting-row"><div><strong>Apariencia</strong><p>Elegí el tema que te resulte más cómodo.</p></div>${btn('Cambiar tema','theme','moon','ghost')}</div><div class="setting-row"><div><strong>Datos de demostración</strong><p>Los cambios se guardan en este navegador.</p></div>${btn('Restablecer','reset-demo','repeat','ghost')}</div><div class="notice">Esta demo permite explorar la gestión de un entrenador. El acceso real de alumnos, las notificaciones y las integraciones de pago se pueden incorporar en el desarrollo final.</div></section>`}
function modal(title,body,submit='',wide=false){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}" ${wide?'style="max-width:800px"':''}><div class="modal-header"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div>${submit?`<form id="modal-form" data-submit="${submit}">${body}<div class="modal-actions"><button type="button" class="ghost" data-action="close-modal">Cancelar</button><button class="primary" type="submit">${icon('check')}Guardar</button></div></form>`:body}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#modal-root input, #modal-root select, #modal-root button')?.focus(),20)}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow=''}
function field(label,name,value='',type='text',extra=''){return `<div class="form-field ${extra}"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" required ${type==='number'?'min="0" step="any"':''}></div>`}
function selectField(label,name,options,value){return `<div class="form-field"><label for="f-${name}">${label}</label><select name="${name}" id="f-${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`}
function clientForm(edit){const c=edit?client(selected):{name:'',email:'',goal:'Ganancia muscular',age:25,height:170,weight:70};modal(edit?'Editar cliente':'Sumá un nuevo cliente',`<div class="form-grid">${field('Nombre y apellido','name',c.name,'text','full')}${field('Email','email',c.email,'email','full')}${selectField('Objetivo','goal',['Ganancia muscular','Recomposición corporal','Bajar de peso','Fuerza y definición','Rendimiento deportivo','Bienestar general'].map(x=>[x,x]),c.goal)}${field('Edad','age',c.age,'number')}${field('Altura (cm)','height',c.height,'number')}${field('Peso (kg)','weight',c.weight,'number')}</div>`,edit?'edit-client':'new-client')}
function sessionForm(date='2026-10-24'){modal('Agendar una sesión',`<div class="form-grid">${selectField('Cliente','client',db.clients.map(c=>[c.id,c.name]),selected)}${selectField('Entrenamiento','type',[['Piernas · Día 1','Piernas · Día 1'],['Tren superior · Día 2','Tren superior · Día 2'],['Full body · Día 3','Full body · Día 3']],0)}${field('Fecha','date',date,'date')}${field('Horario','time','16:00','time')}</div>`,'new-session')}
function paymentForm(paid=true){modal(paid?'Registrar un pago':'Agregar cargo pendiente',`<div class="form-grid">${selectField('Cliente','client',db.clients.map(c=>[c.id,c.name]),selected)}${field('Importe (ARS)','amount',35000,'number')}${field('Fecha','date','2026-10-24','date')}${selectField('Medio de pago','method',[['Transferencia','Transferencia'],['Efectivo','Efectivo'],['Tarjeta','Tarjeta']],0)}</div><div class="notice">Registro de demostración. No se procesa ningún pago real.</div>`,paid?'new-payment':'new-charge')}
function planForm(isNew=false){const c=client(selected),p=db.plans[selected]||{name:c?.plan||'Mi nueva rutina',weeks:3};modal(isNew?'Crear plan de entrenamiento':'Editar plan de entrenamiento',`<div class="form-grid">${isNew?selectField('Asignar a','client',db.clients.map(c=>[c.id,c.name]),selected):''}${field('Nombre del plan','name',p.name)}${field('Duración (semanas)','weeks',p.weeks,'number')}${field('Enfoque Día 1','day0',p.day0||defaults[0].name)}${field('Enfoque Día 2','day1',p.day1||defaults[1].name)}${defaults.map((d,i)=>d.items.map((e,j)=>field(`${e[1]} · series × repeticiones`,'set'+i+j,p['set'+i+j]||e[2])).join('')).join('')}</div>`,isNew?'new-plan':'edit-plan',true)}
function nutritionForm(){const n=db.nutrition[selected]||{name:'Guía de alimentación diaria',calories:2200,breakfast:'Yogur natural, avena y una fruta.',lunch:'Pollo, arroz integral y vegetales.',snack:'Tostadas integrales con queso y fruta.',dinner:'Pescado con papas y ensalada.'};modal('Plan nutricional',`<div class="form-grid">${field('Nombre del plan','name',n.name,'text','full')}${field('Calorías de referencia','calories',n.calories,'number','full')}${['breakfast','lunch','snack','dinner'].map((k,i)=>`<div class="form-field full"><label for="f-${k}">${['Desayuno','Almuerzo','Merienda','Cena'][i]}</label><textarea id="f-${k}" name="${k}" rows="2" required>${esc(n[k])}</textarea></div>`).join('')}</div>`,'nutrition')}
function openReport(id){modal('Informe de ingreso',`<div class="button-group" style="justify-content:flex-end;margin-bottom:18px">${btn('Imprimir / guardar PDF','print','download')}</div>${reportHTML(client(id))}`,'',true)}
function actions(a,target){if(a.startsWith('report-')){openReport(Number(a.slice(7)));return}switch(a){case'close-modal':closeModal();break;case'new-client':clientForm(false);break;case'edit-client':clientForm(true);break;case'new-session':sessionForm();break;case'new-payment':paymentForm();break;case'new-charge':paymentForm(false);break;case'new-plan':planForm(true);break;case'edit-plan':planForm();break;case'new-nutrition':nutritionForm();break;case'client-chat':chatClient=selected;go('mensajes');break;case'archive-client':{const c=client(selected);c.active=!c.active;persist();render();toast(c.active?'Cliente activado':'Cliente archivado');break}case'delete-client':modal('Eliminar cliente',`<p>Se eliminará la ficha de ${esc(client(selected).name)} y sus registros de esta demo.</p><div class="modal-actions"><button class="ghost" data-action="close-modal">Cancelar</button><button class="danger" data-action="confirm-delete">Eliminar cliente</button></div>`);break;case'confirm-delete':db.clients=db.clients.filter(c=>c.id!==selected);db.sessions=db.sessions.filter(s=>s.client!==selected);db.payments=db.payments.filter(p=>p.client!==selected);delete db.nutrition[selected];delete db.plans[selected];delete db.notes[selected];persist();closeModal();go('clientes');toast('Cliente eliminado');break;case'save-template':{const name=(db.plans[selected]||{}).name||client(selected).plan;db.templates=db.templates||[];db.templates.push(name+' · copia');persist();toast('Rutina guardada en Plantillas');break}case'exercise-note':target.closest('.exercise').classList.toggle('open');break;case'month-prev':month--;if(month<0){month=11;year--}render();break;case'month-next':month++;if(month>11){month=0;year++}render();break;case'month-today':month=9;year=2026;render();break;case'print':window.print();break;case'checkin':modal('Registrar check-in',`<div class="form-grid">${field('Peso actual (kg)','weight',client(selected).weight,'number')}${selectField('Energía','energy',[1,2,3,4,5].map(x=>[x,x+' / 5']),5)}<div class="form-field full"><label for="f-note">Notas del entrenamiento</label><textarea id="f-note" name="note" rows="3" required placeholder="¿Cómo se sintió en la sesión?"></textarea></div></div>`,'checkin');break;case'theme':toggleTheme();break;case'reset-demo':modal('Restablecer la demo',`<p>Se borrarán los cambios de este navegador y volverán los datos de ejemplo.</p><div class="modal-actions"><button class="ghost" data-action="close-modal">Cancelar</button><button class="primary" data-action="confirm-reset">Restablecer datos</button></div>`);break;case'confirm-reset':db=structuredClone(initial);persist();closeModal();go('inicio');toast('Demo restablecida');break;case'timer-toggle':timerRunning=!timerRunning;if(timerRunning){timerId=setInterval(()=>{timerSeconds++;if($('#timer'))$('#timer').textContent=formatTime(timerSeconds)},1000)}else clearInterval(timerId);render();break;case'timer-reset':timerSeconds=0;timerRunning=false;clearInterval(timerId);render();break;case'steps':case'calories':modal(a==='steps'?'Registrar pasos':'Registrar calorías',`<div class="form-grid">${field(a==='steps'?'Pasos del día':'Consumo del día (kcal)','value',a==='steps'?(db.steps||7250):(db.calories||1850),'number','full')}</div>`,a);break;case'export-payments':{const list=db.payments.filter(p=>page!=='perfil'||p.client===selected);const rows=[['Cliente','Fecha','Importe ARS','Estado','Medio'],...list.map(p=>[client(p.client)?.name||'Cliente',p.date,p.amount,p.paid?'Pagado':'Pendiente',p.method])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='fit-cobros-demo.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),500);toast('Exportación de cobros descargada');break}}
}
function toggleTheme(){document.body.classList.toggle('light');localStorage.setItem('fit-theme',document.body.classList.contains('light')?'light':'dark')}
document.addEventListener('click',e=>{const goEl=e.target.closest('[data-go]');if(goEl){go(goEl.dataset.go);return}const profile=e.target.closest('[data-profile]');if(profile){go('perfil',profile.dataset.profile);return}const tabEl=e.target.closest('[data-tab]');if(tabEl){tab=tabEl.dataset.tab;const pos=$('.tabs').scrollLeft;render();$('.tabs').scrollLeft=pos;return}const action=e.target.closest('[data-action]');if(action){actions(action.dataset.action,action);return}const date=e.target.closest('[data-date]');if(date){const sessions=db.sessions.filter(s=>s.date===date.dataset.date&&(page!=='perfil'||s.client===selected));modal('Sesiones · '+date.dataset.date.split('-').reverse().join('/'),`${sessions.length?sessions.map(s=>`<div class="client-row">${avatar(client(s.client))}<div><strong>${esc(client(s.client).name)}</strong><small>${s.time} · ${esc(s.type)}</small></div><button class="small ghost" data-session-done="${s.id}">${s.done?'Completada':'Completar'}</button><button class="icon-btn" data-session-delete="${s.id}" aria-label="Eliminar sesión">${icon('trash')}</button></div>`).join(''):'<p>No hay sesiones para esta fecha.</p>'}<div class="modal-actions"><button class="primary" data-add-date="${date.dataset.date}">${icon('plus')}Agendar sesión</button></div>`);return}const ad=e.target.closest('[data-add-date]');if(ad){sessionForm(ad.dataset.addDate);return}const done=e.target.closest('[data-session-done]');if(done){const s=db.sessions.find(x=>x.id===+done.dataset.sessionDone);s.done=!s.done;persist();closeModal();render();toast(s.done?'Sesión completada':'Sesión pendiente');return}const del=e.target.closest('[data-session-delete]');if(del){db.sessions=db.sessions.filter(s=>s.id!==+del.dataset.sessionDelete);persist();closeModal();render();toast('Sesión eliminada de la demo');return}const paid=e.target.closest('[data-paid]');if(paid){db.payments.find(p=>p.id===+paid.dataset.paid).paid=true;persist();render();toast('Pago registrado');return}const chat=e.target.closest('[data-chat]');if(chat){chatClient=+chat.dataset.chat;render();return}const nut=e.target.closest('[data-nutrition]');if(nut){selected=+nut.dataset.nutrition;page='perfil';tab='nutricion';render();window.scrollTo(0,0);return}const template=e.target.closest('[data-template]');if(template){window.templateToAssign=template.dataset.template;modal('Asignar plantilla',`<div class="form-grid">${selectField('Cliente','client',db.clients.map(c=>[c.id,c.name]),selected)}</div><div class="notice">${esc(window.templateToAssign)} · La plantilla reemplazará el plan de este cliente en la demo.</div>`,'assign-template');return}const tech=e.target.closest('[data-technique]');if(tech){modal(esc(tech.dataset.technique),`<div class="resource-visual">${icon('dumbbell')}</div><p>Realizá el movimiento con una postura estable y controlá tanto la subida como la bajada. Ajustá la carga para completar la serie con buena técnica.</p><div class="notice">Ficha ilustrativa. La biblioteca final puede incorporar videos y pautas específicas de cada ejercicio.</div>`);return}if(e.target.classList.contains('modal-backdrop'))closeModal()});
document.addEventListener('input',e=>{if(e.target.id==='client-search'){query=e.target.value;$('#client-results').innerHTML=clientCards()}if(e.target.id==='exercise-search'){$('#exercise-results').innerHTML=exerciseCards(defaults.flatMap(d=>d.items).filter(x=>x.join(' ').toLowerCase().includes(e.target.value.toLowerCase())))}});
document.addEventListener('change',e=>{if(e.target.id==='status-filter'){clientFilter=e.target.value;$('#client-results').innerHTML=clientCards()}if(e.target.id==='chart-mode'){chartMode=e.target.value;render()}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='chat-form'){const data=new FormData(e.target),text=data.get('message').trim();if(!text)return;db.messages.push({client:chatClient,text});persist();render();$('#chat-messages').scrollTop=99999;return}if(e.target.id!=='modal-form')return;const type=e.target.dataset.submit,f=Object.fromEntries(new FormData(e.target));switch(type){case'new-client':db.clients.push({...f,id:Date.now(),active:true,color:'#a6c96a',plan:'Plan inicial',age:+f.age,height:+f.height,weight:+f.weight});break;case'edit-client':Object.assign(client(selected),f,{age:+f.age,height:+f.height,weight:+f.weight});break;case'new-session':db.sessions.push({...f,id:Date.now(),client:+f.client,done:false});break;case'new-payment':case'new-charge':db.payments.push({...f,id:Date.now(),client:+f.client,amount:+f.amount,paid:type==='new-payment'});break;case'new-plan':selected=+f.client;db.plans[selected]=f;client(selected).plan=f.name;page='perfil';tab='plan';break;case'edit-plan':db.plans[selected]=f;client(selected).plan=f.name;break;case'nutrition':db.nutrition[selected]=f;break;case'checkin':client(selected).weight=+f.weight;db.notes[selected]=f.note;db.checkins=db.checkins||{};db.checkins[selected]={energy:+f.energy,weight:+f.weight};break;case'assign-template':selected=+f.client;db.plans[selected]={name:window.templateToAssign,weeks:3};client(selected).plan=window.templateToAssign;page='perfil';tab='plan';break;case'steps':db.steps=+f.value;break;case'calories':db.calories=+f.value;break}persist();closeModal();render();toast('Cambios guardados en la demo')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.body.classList.remove('nav-open')}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-profile],[data-chat]')){e.preventDefault();e.target.click()}if(e.key==='Tab'&&$('.modal')){const nodes=[...$('.modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
$('#nav-overlay').onclick=()=>document.body.classList.remove('nav-open');$('#theme-button').onclick=toggleTheme;$('#search-button').onclick=()=>{go('clientes');$('#client-search').focus()};$('#notifications').onclick=()=>modal('Tu actividad al día',`<div class="activity"><div class="activity-icon">${icon('circleCheck')}</div><div><strong>Dos clientes completaron su sesión</strong><p>Revisá su progreso y registrá tus observaciones.</p></div></div><div class="activity"><div class="activity-icon">${icon('wallet')}</div><div><strong>Tenés dos cobros pendientes</strong><p>Podés ver el detalle en la sección Cobros.</p></div></div><div class="modal-actions"><button class="primary" data-go="cobros" onclick="closeModal()">Ver cobros</button></div>`);
if(localStorage.getItem('fit-theme')==='light')document.body.classList.add('light');render();
